#include <string>
#include <utility>
#include <vector>
struct Device { std::string id; std::string name; };
enum class AddDeviceResult { added, emptyId, duplicateId };

AddDeviceResult addDevice(std::vector<Device>& devices, Device candidate) {
    if (candidate.id.empty()) return AddDeviceResult::emptyId;
    for (const auto& d : devices)
        if (d.id == candidate.id) return AddDeviceResult::duplicateId;
    devices.push_back(std::move(candidate));
    return AddDeviceResult::added;
}

#include <cassert>
#include <vector>
// Использует Device и addDevice из BC03.
void duplicateDoesNotChangeMap() {
    std::vector<Device> devices{{"sw-1", "Access"}};
    const auto result = addDevice(devices, {"sw-1", "Other"});
    assert(result == AddDeviceResult::duplicateId);
    assert(devices.size() == 1);
    assert(devices.front().name == "Access");
}

